async function invoke(body){
 const {data,error}=await db.functions.invoke('admin-manage-user',{body});
 if(error){
  let message=data?.error||data?.message||'';
  try{
   const response=error.context;
   if(!message&&response){
    const copy=response.clone?response.clone():response;
    const type=copy.headers?.get?.('content-type')||'';
    if(type.includes('application/json')){
     const payload=await copy.json();
     message=payload?.error||payload?.message||''
    }else{
     const txt=await copy.text();
     if(txt)message=txt.slice(0,300)
    }
   }
  }catch(_){}
  throw new Error(message||error.message||'Action impossible')
 }
 if(data?.error)throw new Error(data.error);
 return data
}
