async function cancelResetRequest(requestId,userId){
 if(!requestId||!userId)return;
 if(!confirm('Annuler cette demande de réinitialisation de mot de passe ?'))return;
 try{
  const data=await invoke({action:'cancel-reset',reset_request_id:requestId});
  if(!data?.success)throw new Error(data?.error||'Action impossible');
  requestedResetId=null;
  history.replaceState({},'',location.pathname+'?user='+encodeURIComponent(userId));
  window.NettoSounds?.play?.('delete');
  await Promise.all([loadResetRequests(),loadUsers(),loadLogs(false)]);
  selectUser(userId,false)
 }catch(e){
  window.NettoSounds?.play?.('error');
  alert('Impossible d’annuler la demande : '+e.message)
 }
}

