async function resolveEmailResetRequest(requestId,userId){
 if(!requestId||!userId)return;
 if(!confirm('Réinitialiser l’adresse e-mail de récupération ? L’ancienne adresse sera supprimée et l’utilisateur pourra en enregistrer une nouvelle depuis Mon profil.'))return;
 try{
  const data=await invoke({action:'reset-recovery-email',email_reset_request_id:requestId,user_id:userId});
  if(!data?.success)throw new Error(data?.error||'Action impossible');
  requestedEmailResetId=null;
  history.replaceState({},'',location.pathname+'?user='+encodeURIComponent(userId));
  window.NettoSounds?.play?.('success');
  await Promise.all([loadEmailResetRequests(),loadUsers(),loadLogs(false)]);
  selectUser(userId,false);
  const state=$('saveState');if(state){state.className='state ok';state.textContent='✓ Adresse e-mail de récupération réinitialisée.'}
 }catch(e){
  window.NettoSounds?.play?.('error');
  alert('Impossible de réinitialiser l’adresse e-mail : '+e.message)
 }
}

async function saveSelected(){const u=users.find(x=>x.id===selectedId);if(!u)return;const btn=$('saveUserBtn'),state=$('saveState'),reset=pendingResetFor(u.id),payload={action:'update',user_id:u.id,display_name:$('editName').value.trim(),username:$('editUsername').value.trim(),role:$('editRole').value,profile_color:$('editColor').value,avatar_frame:$('editAvatarFrame').value,planning_name:$('editPlanningName').value,password:$('editPassword').value,reset_request_id:(requestedResetId&&resetRequests.some(r=>r.id===requestedResetId&&r.user_id===u.id)?requestedResetId:reset?.id)||''};if(u.id===session.user.id&&payload.role!=='admin'&&!confirm('Tu modifies ton propre rôle administrateur. Après enregistrement tu pourrais perdre l’accès à cette page. Continuer ?'))return;if(reset&&!payload.password){state.className='state err';state.textContent='Saisis un nouveau mot de passe pour traiter la demande de réinitialisation.';window.NettoSounds?.play?.('warning');return}btn.disabled=true;state.className='state';state.textContent='Enregistrement…';try{const data=await invoke(payload);state.className='state ok';state.textContent=data.reset_resolved?'✓ Mot de passe réinitialisé et demande clôturée.':'✓ Compte mis à jour'+(data.changed_fields?.length?' · '+data.changed_fields.length+' champ(s) modifié(s)':'');window.NettoSounds?.play?.('success');if(data.reset_resolved){requestedResetId=null;history.replaceState({},'',location.pathname+'?user='+encodeURIComponent(u.id))}await Promise.all([loadResetRequests(),loadUsers(),loadLogs(false)]);selectUser(u.id,false)}catch(e){state.className='state err';state.textContent='Erreur : '+e.message;window.NettoSounds?.play?.('error')}finally{btn.disabled=false}}
