async function createCustomRole(){const label=$('newRoleLabel').value.trim(),btn=$('createRoleBtn'),state=$('newRoleState');if(label.length<2){state.className='state err';state.textContent='Le nom doit contenir au moins 2 caractères.';return}btn.disabled=true;state.className='state';state.textContent='Création…';try{let key=roleSlug(label);if(appRoles.some(r=>r.key===key))key=(key.slice(0,27)+'_'+Date.now().toString(36).slice(-4)).slice(0,32);const position=Math.max(50,...appRoles.map(r=>Number(r.position)||0))+10;const {error}=await db.from('app_roles').insert({key,label,is_system:false,position,created_by:session.user.id});if(error)throw error;await loadAppRoles();siteConfig.role_definitions=Object.fromEntries(appRoles.map(r=>[r.key,{label:r.label,is_system:r.is_system}]));$('roleDialog').close();renderRoleMatrix();await saveRolePermissions();window.NettoSounds?.play?.('success')}catch(e){state.className='state err';state.textContent='Erreur : '+e.message;window.NettoSounds?.play?.('error')}finally{btn.disabled=false}}
async function deleteCustomRole(key){const r=appRoles.find(x=>x.key===key);if(!r||r.is_system)return;const {count,error:countError}=await db.from('profiles').select('id',{count:'exact',head:true}).eq('role',key);if(countError)return alert('Impossible de vérifier l’utilisation de ce rôle.');if(count){window.NettoSounds?.play?.('warning');return alert('Ce rôle est attribué à '+count+' compte'+(count>1?'s':'')+'. Change leur rôle avant de le supprimer.')}if(!confirm('Supprimer le rôle « '+r.label+' » ?'))return;const {error}=await db.from('app_roles').delete().eq('key',key);if(error){window.NettoSounds?.play?.('error');return alert('Suppression impossible : '+error.message)}for(const m of Object.values(siteConfig.role_permissions||{}))if(m&&typeof m==='object')delete m[key];for(const w of Object.values(siteConfig.planning_widgets||{}))if(w&&typeof w==='object')delete w[key];for(const w of Object.values(siteConfig.home_widgets||{}))if(w?.roles&&typeof w.roles==='object')delete w.roles[key];for(const p of Object.values(siteConfig.pages||{}))if(Array.isArray(p?.roles))p.roles=p.roles.filter(x=>x!==key);await loadAppRoles();siteConfig.role_definitions=Object.fromEntries(appRoles.map(r=>[r.key,{label:r.label,is_system:r.is_system}]));renderRoleMatrix();await saveRolePermissions();window.NettoSounds?.play?.('delete')}
