async function deleteSubrole(key){const s=subroles.find(x=>x.key===key);if(!s)return;const count=userSubroles.filter(x=>x.subrole_key===key).length;if(count&&!confirm('Ce sous-rôle est attribué à '+count+' compte'+(count>1?'s':'')+'. Le supprimer retirera ces attributions. Continuer ?'))return;if(!count&&!confirm('Supprimer le sous-rôle « '+s.label+' » ?'))return;const {error}=await db.from('app_subroles').delete().eq('key',key);if(error){window.NettoSounds?.play?.('error');return alert('Suppression impossible : '+error.message)}for(const w of Object.values(siteConfig.home_widgets||{}))if(w?.subroles&&typeof w.subroles==='object')delete w.subroles[key];await db.from('app_settings').upsert({key:'site_config',value:siteConfig,updated_by:session.user.id,updated_at:new Date().toISOString()},{onConflict:'key'});await loadSubroles();if(selectedId)selectUser(selectedId,false);window.NettoSounds?.play?.('delete')}
function renderSubroleMatrix(){const host=$('subroleMatrix');if(!host)return;if(!subroles.length){host.innerHTML='<div class="empty">Crée un sous-rôle pour ajouter une couche de permissions.</div>';return}const mods=roleModules();host.innerHTML='<table><thead><tr><th>Module</th>'+subroles.map(s=>'<th>'+esc(s.label)+'</th>').join('')+'</tr></thead><tbody>'+mods.map(m=>'<tr><td><div class="roleModule"><strong>'+esc(m.homeLabel||m.label||m.id)+'</strong><small>'+esc(m.subtitle||m.description||m.id)+'</small></div></td>'+subroles.map(s=>'<td><select class="permSelect" data-subrole-module="'+esc(m.id)+'" data-subrole-key="'+esc(s.key)+'" onchange="this.dataset.level=this.value;markSubroleDirty()"><option value="none">Aucun ajout</option><option value="view">Consultation</option>'+(m.id==='stock'?'<option value="operate">Opérationnel</option>':'')+'<option value="manage">Gestion</option></select></td>').join('')+'</tr>').join('')+'</tbody></table>';loadSubroleMatrixValues()}
async function loadSubroleMatrixValues(){if(!subroles.length)return;const {data,error}=await db.from('subrole_module_permissions').select('subrole_key,module,permission');if(error)return console.warn(error);for(const row of data||[]){const el=document.querySelector('[data-subrole-module="'+CSS.escape(row.module)+'"][data-subrole-key="'+CSS.escape(row.subrole_key)+'"]');if(el){el.value=row.permission;el.dataset.level=row.permission}}}
